/**
  * @brief  The application entry point.
  * @retval int
  */
int main(void)
{

  /* USER CODE BEGIN 1 */
  /* Enable AXISRAM3..6: used for heap allocation */

  /* Power up the memory arrays clearing the shutdown bit for each bank */
  __HAL_RCC_RAMCFG_CLK_ENABLE();
  RAMCFG_SRAM3_AXI_S->CR &= ~RAMCFG_CR_SRAMSD;
  RAMCFG_SRAM4_AXI_S->CR &= ~RAMCFG_CR_SRAMSD;
  RAMCFG_SRAM5_AXI_S->CR &= ~RAMCFG_CR_SRAMSD;
  RAMCFG_SRAM6_AXI_S->CR &= ~RAMCFG_CR_SRAMSD;

  /* Enable the memory clocks */
  __HAL_RCC_AXISRAM3_MEM_CLK_ENABLE();
  __HAL_RCC_AXISRAM4_MEM_CLK_ENABLE();
  __HAL_RCC_AXISRAM5_MEM_CLK_ENABLE();
  __HAL_RCC_AXISRAM6_MEM_CLK_ENABLE();

  /* Release from reset */
  RCC->MEMRSTCR = RCC_MEMRSTCR_AXISRAM3RSTC | RCC_MEMRSTCR_AXISRAM4RSTC |
                  RCC_MEMRSTCR_AXISRAM5RSTC | RCC_MEMRSTCR_AXISRAM6RSTC;

  /* Enable I-cache and D-cache */
  MEMSYSCTL->MSCR |= MEMSYSCTL_MSCR_ICACTIVE_Msk;
  MEMSYSCTL->MSCR |= MEMSYSCTL_MSCR_DCACTIVE_Msk;
  SCB_EnableICache();
  SCB_EnableDCache();
  /* USER CODE END 1 */

  /* MCU Configuration--------------------------------------------------------*/
  HAL_Init();

  /* USER CODE BEGIN Init */

  /* USER CODE END Init */

  /* Configure the system clock */
  SystemClock_Config();

  /* Configure the peripherals common clocks */
  PeriphCommonClock_Config();

  /* USER CODE BEGIN SysInit */

  /* USER CODE END SysInit */

  /* Initialize all configured peripherals */
  MX_GPIO_Init();
  MX_GPDMA1_Init();
  MX_DCMIPP_Init();
  MX_I3C2_Init();
  MX_TIM2_Init();
  MX_LPUART1_UART_Init();
  MX_I3C1_Init();
  SystemIsolation_Config();
  /* USER CODE BEGIN 2 */
  HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1); // enable external clock generation
  /* USER CODE END 2 */

  /* Initialize leds */
  BSP_LED_Init(LED_BLUE);
  BSP_LED_Init(LED_RED);
  BSP_LED_Init(LED_GREEN);

  /* Infinite loop */
  /* USER CODE BEGIN WHILE */
  while (1)
  {
    /* USER CODE END WHILE */

    /* USER CODE BEGIN 3 */
    vl53l9_app();
  }
  /* USER CODE END 3 */
}
